reference_solution:
def subsets(nums):
    res, cur = [], []
    def bt(start):
        res.append(cur[:])
        for i in range(start, len(nums)):
            cur.append(nums[i])
            bt(i + 1)
            cur.pop()
    bt(0)
    return res

brute_force_solution:
import itertools
def subsets(nums):
    return [list(c) for k in range(len(nums) + 1) for c in itertools.combinations(nums, k)]

